1	// ============================================================================
2	// FreeLang Index Manager 모듈 - 인덱스 자동 빌드/관리 (Phase 12)
3	// ============================================================================
4	// 목표: 컬럼별 INT/STR 인덱스를 일원화하여 관리
5	// 원리: IndexManager는 컬럼별 인덱스 슬롯을 유지하고, 동적으로 빌드/조회
6	// ============================================================================
7	
8	module index_manager {
9	    // === 에러 코드 ===
10	    const IDX_MGR_OK:         i32 = 0;
11	    const IDX_MGR_ERR_FULL:   i32 = 200;
12	    const IDX_MGR_ERR_NOTFOUND: i32 = 201;
13	    const IDX_MGR_ERR_TYPE:   i32 = 202;
14	
15	    const MAX_IDX_COLS: i32 = 16;  // schema.MAX_COLS와 동일
16	
17	    // === 인덱스 매니저 구조체 ===
18	    struct IndexManager {
19	        // INT 인덱스 레지스트리
20	        int_indices:    [index.BTreeIndex];   // [MAX_IDX_COLS]
21	        int_idx_active: [bool];
22	        int_idx_count:  i32;
23	
24	        // STR 인덱스 레지스트리
25	        str_indices:    [index_str.StrIndex]; // [MAX_IDX_COLS]
26	        str_idx_active: [bool];
27	        str_idx_count:  i32;
28	    }
29	
30	    // === 초기화 ===
31	
32	    func index_manager_new() -> IndexManager {
33	        let im = IndexManager{
34	            int_indices:    make([index.BTreeIndex], MAX_IDX_COLS),
35	            int_idx_active: make([bool], MAX_IDX_COLS),
36	            int_idx_count:  0,
37	            str_indices:    make([index_str.StrIndex], MAX_IDX_COLS),
38	            str_idx_active: make([bool], MAX_IDX_COLS),
39	            str_idx_count:  0,
40	        };
41	
42	        // 모든 슬롯을 비활성으로 초기화
43	        let idx = 0;
44	        for idx = 0; idx < MAX_IDX_COLS; idx = idx + 1 {
45	            im.int_idx_active[idx] = false;
46	            im.str_idx_active[idx] = false;
47	        }
48	
49	        return im;
50	    }
51	
52	    // === INT 인덱스 빌드 ===
53	    // 테이블의 INT 컬럼을 BTreeIndex로 인덱싱
54	    // 성공 시 IDX_MGR_OK, 실패 시 에러 코드 반환
55	    func index_manager_build_int(im: *IndexManager, t: schema.Table, col_idx: i32) -> i32 {
56	        // 검증
57	        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
58	            return IDX_MGR_ERR_NOTFOUND;
59	        }
60	
61	        if col_idx >= t.schema.col_count {
62	            return IDX_MGR_ERR_NOTFOUND;
63	        }
64	
65	        if t.schema.col_defs[col_idx].col_type != schema.COL_TYPE_INT {
66	            return IDX_MGR_ERR_TYPE;
67	        }
68	
69	        // 이미 활성화되어 있으면 재구축
70	        if im.int_idx_active[col_idx] {
71	            // 기존 인덱스 대체 (재초기화)
72	            im.int_indices[col_idx] = index.index_new(col_idx);
73	        } else {
74	            // 새 인덱스 생성
75	            im.int_indices[col_idx] = index.index_new(col_idx);
76	            im.int_idx_active[col_idx] = true;
77	            im.int_idx_count = im.int_idx_count + 1;
78	        }
79	
80	        // 테이블의 모든 행을 인덱스에 삽입
81	        let row_idx = 0;
82	        for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
83	            // 삭제된 행 스킵
84	            if t.deleted_flags[row_idx] {
85	                continue;
86	            }
87	
88	            // SoA 레이아웃: [col_idx * MAX_ROWS + row_idx]
89	            let soa_idx = col_idx * schema.MAX_ROWS + row_idx;
90	            let key = t.int_cols[soa_idx];
91	            let row_id = t.row_ids[row_idx];
92	
93	            // 인덱스 삽입 시도
94	            let result = im.int_indices[col_idx].index_insert(key, row_id);
95	
96	            // MAX_KEYS 초과 시 (노드 분할 미구현) 폴백
97	            if result == index.IDX_ERR_FULL {
98	                // 인덱스 빌드 실패 → 활성화 해제 (FULL_SCAN으로 폴백)
99	                im.int_idx_active[col_idx] = false;
100	                im.int_idx_count = im.int_idx_count - 1;
101	                return IDX_MGR_ERR_FULL;
102	            }
103	        }
104	
105	        return IDX_MGR_OK;
106	    }
107	
108	    // === STR 인덱스 빌드 ===
109	    // 테이블의 STR 컬럼을 StrIndex로 인덱싱
110	    func index_manager_build_str(im: *IndexManager, t: schema.Table, col_idx: i32) -> i32 {
111	        // 검증
112	        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
113	            return IDX_MGR_ERR_NOTFOUND;
114	        }
115	
116	        if col_idx >= t.schema.col_count {
117	            return IDX_MGR_ERR_NOTFOUND;
118	        }
119	
120	        if t.schema.col_defs[col_idx].col_type != schema.COL_TYPE_STR {
121	            return IDX_MGR_ERR_TYPE;
122	        }
123	
124	        // 이미 활성화되어 있으면 재구축
125	        if im.str_idx_active[col_idx] {
126	            im.str_indices[col_idx] = index_str.str_index_new(col_idx);
127	        } else {
128	            im.str_indices[col_idx] = index_str.str_index_new(col_idx);
129	            im.str_idx_active[col_idx] = true;
130	            im.str_idx_count = im.str_idx_count + 1;
131	        }
132	
133	        // 테이블의 모든 행을 인덱스에 삽입
134	        let row_idx = 0;
135	        for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
136	            // 삭제된 행 스킵
137	            if t.deleted_flags[row_idx] {
138	                continue;
139	            }
140	
141	            // SoA 레이아웃: [col_idx * MAX_ROWS + row_idx]
142	            let soa_idx = col_idx * schema.MAX_ROWS + row_idx;
143	            let key = t.str_cols[soa_idx];
144	            let row_id = t.row_ids[row_idx];
145	
146	            // 인덱스 삽입 시도
147	            let result = im.str_indices[col_idx].str_insert(key, row_id);
148	
149	            // FULL 시 폴백
150	            if result == index_str.STR_IDX_ERR_FULL {
151	                im.str_idx_active[col_idx] = false;
152	                im.str_idx_count = im.str_idx_count - 1;
153	                return IDX_MGR_ERR_FULL;
154	            }
155	        }
156	
157	        return IDX_MGR_OK;
158	    }
159	
160	    // === INT 인덱스 유무 확인 ===
161	    func index_manager_has_int(im: *IndexManager, col_idx: i32) -> bool {
162	        if col_idx < 0 || col_idx >= MAX_IDX_COLS {
163	            return false;
164	        }
