208	    // === 헬퍼 함수: i32 → string ===
209	    func i32_to_string(n: i32) -> string {
210	        if n == 0 {
211	            return "0";
212	        }
213	
214	        let negative = false;
215	        let num = n;
216	        if num < 0 {
217	            negative = true;
218	            num = 0 - num;
219	        }
220	
221	        let digits = make([i32], 16);
222	        let digit_count = 0;
223	        let temp = num;
224	
225	        for temp > 0 {
226	            let digit = temp % 10;
227	            digits[digit_count] = digit;
228	            digit_count = digit_count + 1;
229	            temp = temp / 10;
230	        }
231	
232	        let result = "";
233	        if negative {
234	            result = "-";
235	        }
236	
237	        let idx = digit_count - 1;
238	        for idx >= 0 {
239	            let ch_code = 48 + digits[idx];
240	            result = result + chr(ch_code);
241	            idx = idx - 1;
242	        }
243	
244	        return result;
245	    }
246	}
