48	    // === 문자열 비교 함수 ===
49	
50	    // 두 문자열 비교: a < b → -1, a == b → 0, a > b → 1
51	    // 사전식(lexicographic) 순서로 비교
52	    @inline
53	    func str_cmp(a: string, b: string) -> i32 {
54	        let a_len = len(a);
55	        let b_len = len(b);
56	        let min_len = a_len;
57	        if b_len < min_len {
58	            min_len = b_len;
59	        }
60	
61	        let i = 0;
62	        for i = 0; i < min_len; i = i + 1 {
63	            let a_ch = char_at(a, i);
64	            let b_ch = char_at(b, i);
65	            if a_ch < b_ch {
66	                return -1;
67	            }
68	            if a_ch > b_ch {
69	                return 1;
70	            }
71	        }
72	
73	        if a_len < b_len {
74	            return -1;
75	        }
76	        if a_len > b_len {
77	            return 1;
78	        }
79	        return 0;
80	    }

