168	    // === 헬퍼: i32 → string ===
169	    func i32_to_string(n: i32) -> string {
170	        if n == 0 {
171	            return "0";
172	        }
173	
174	        let negative = false;
175	        let num = n;
176	        if num < 0 {
177	            negative = true;
178	            num = 0 - num;
179	        }
180	
181	        let digits = make([i32], 16);
182	        let digit_count = 0;
183	        let temp = num;
184	
185	        for temp > 0 {
186	            let digit = temp % 10;
187	            digits[digit_count] = digit;
188	            digit_count = digit_count + 1;
189	            temp = temp / 10;
190	        }
191	
192	        let result = "";
193	        if negative {
194	            result = "-";
195	        }
196	
197	        let idx = digit_count - 1;
198	        for idx >= 0 {
199	            let ch_code = 48 + digits[idx];
200	            result = result + chr(ch_code);
201	            idx = idx - 1;
202	        }
203	
204	        return result;
205	    }
