### 3-7. `index_insert` 수정 (index.fl)

기존 라인 140-142의 `IDX_ERR_FULL` 조기 반환을 분할 호출로 교체한다.

**교체할 코드** (현재):
```
if leaf.key_count >= MAX_KEYS {
    return IDX_ERR_FULL;  // 분할 미구현 (간단화)
}
```

**교체 후 코드**:
```
func (idx: *BTreeIndex) index_insert(key: i64, row_id: i64) -> i32 {
    if idx.node_count >= MAX_NODES {
        return IDX_ERR_FULL;
    }

    // 경로 추적을 위한 버퍼 (루트까지의 내부 노드 인덱스 스택)
    let path = make([i32], 100);
    let path_depth = 0;

    let leaf_idx = idx.find_leaf_with_path(key, path, &path_depth);
    let leaf = idx.nodes[leaf_idx];

    // 분할이 필요한 경우
    if leaf.key_count >= MAX_KEYS {
        // 먼저 키를 임시 배열에 삽입 후 분할
        // split_leaf 는 현재 8개 꽉 찬 리프를 2개로 나눔
        let new_right, sep_key = idx.split_leaf(leaf_idx);
        if new_right == -1 {
            return IDX_ERR_FULL;
        }

        // 분할 후 올바른 리프를 다시 찾아서 삽입
        // sep_key 기준: key < sep_key → 왼쪽(leaf_idx), key >= sep_key → 오른쪽(new_right)
        if key >= sep_key {
            leaf_idx = new_right;
        }

        // 부모에 separator key 삽입 (전파 처리 포함)
        idx.insert_into_parent(leaf_idx == new_right ? leaf_idx - 1 : leaf_idx,
                               sep_key, new_right, path, path_depth);

        // 분할 후 해당 리프 다시 로드
        // 주의: insert_into_parent 후 루트가 바뀔 수 있으므로
        //       leaf_idx는 여전히 유효하다 (노드 풀 인덱스 불변)
    }

    // (분할 여부와 관계없이) 올바른 리프에 키 삽입
    let target_leaf = idx.nodes[leaf_idx];
    ...
}
```

**주의**: 위 의사코드에서 삼항 연산자(`?:`)가 FreeLang에 없으므로 if-else 로 풀어야 한다. 또한 `split_leaf` 는 key를 실제로 삽입하지 않으므로, 분할 후 leaf는 4개 키를 가진 상태가 되어 삽입 공간이 생긴다.

**정확한 수정 코드 흐름**:

```
func (idx: *BTreeIndex) index_insert(key: i64, row_id: i64) -> i32 {
    if idx.node_count >= MAX_NODES {
        return IDX_ERR_FULL;
    }

    let path = make([i32], 100);
    let path_depth = 0;
    let leaf_idx = idx.find_leaf_with_path(key, path, &path_depth);

    let leaf = idx.nodes[leaf_idx];
    if leaf.key_count >= MAX_KEYS {
        // 노드 풀에 최소 2개 여유가 있어야 분할 가능
        // (리프 분할 1개 + 연쇄 내부 분할 가능성)
        if idx.node_count + 2 > MAX_NODES {
            return IDX_ERR_FULL;
        }

        let new_right, sep_key = idx.split_leaf(leaf_idx);
        if new_right == -1 {
            return IDX_ERR_FULL;
        }

        // 부모에 separator 삽입 (연쇄 분할 처리)
        idx.insert_into_parent(leaf_idx, sep_key, new_right, path, path_depth);

        // 새 키가 어느 리프에 들어가야 하는지 결정
        if key >= sep_key {
            leaf_idx = new_right;
        }
        // leaf 변수를 갱신
        leaf = idx.nodes[leaf_idx];
    }

    // 삽입 위치 찾기 (기존 로직)
    let pos = leaf.key_count;
    let i = 0;
    for i = 0; i < leaf.key_count; i = i + 1 {
        if key < leaf.keys[i] {
            pos = i;
            break;
        }
    }

    // 키 삽입 (오른쪽으로 시프트)
    let j = leaf.key_count;
    for j > pos {
        leaf.keys[j]   = leaf.keys[j - 1];
        leaf.row_ids[j] = leaf.row_ids[j - 1];
        j = j - 1;
    }
    leaf.keys[pos]   = key;
    leaf.row_ids[pos] = row_id;
    leaf.key_count   = leaf.key_count + 1;

    idx.nodes[leaf_idx] = leaf;
    idx.key_count = idx.key_count + 1;
    return IDX_OK;
}
```

**FreeLang 주의점**: `let leaf = ...` 로 선언 후 `leaf = idx.nodes[leaf_idx]` 로 재할당이 가능한지 확인 필요. 기존 코드에서 재할당 패턴이 보이지 않는다면 다른 변수명을 사용해야 한다.

